"""Indicadores municipais do Comex Stat: valores, períodos e concentração."""
FONTE='https://www.gov.br/mdic/pt-br/assuntos/comercio-exterior/estatisticas/base-de-dados-bruta'
NOTA='MDIC/Secex · Comex Stat, bens. Localização pelo domicílio fiscal da empresa declarante. Valores em dólares correntes FOB; não são faturamento, arrecadação ou produção local. Peso é o peso líquido declarado, em kg. As classificações de produtos e os cadastros podem mudar ao longo do tempo. Municípios ausentes da tabela MDIC ficam indisponíveis, sem preencher com zero.'
NOTA_EN='MDIC/Secex · Comex Stat, goods. Location is the declaring company’s fiscal domicile. Values are current US dollars FOB, not company revenue, taxes or local production. Weight is reported net weight in kg. Product classifications and registers may change over time. Municipalities absent from the MDIC table remain unavailable, never filled with zero.'
CONDICOES={0:'Registrado no período informado',1:'Zero / sem registro de operações',2:'Indisponível',3:'Denominador ausente',4:'Denominador zero',5:'Fora da cobertura',16:'Cobertura territorial ou populacional incompleta'}
MESES=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro']
MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December']
BASES=[('fob','Valor FOB','FOB value','US$ FOB',False),('kg','Peso líquido declarado','Reported net weight','kg',False),('prod_n','Grupos de produtos (SH4)','Product groups (HS4)','grupos SH4',False),('pais_n','Destinos ou origens (códigos MDIC)','Destinations or origins (MDIC codes)','códigos de mercado',False),('p1_fob','Maior grupo de produtos: valor','Largest product group: value','US$ FOB',True),('p3_fob','Três maiores grupos de produtos: valor','Top three product groups: value','US$ FOB',True),('c1_fob','Maior mercado: valor','Largest market: value','US$ FOB',True),('c3_fob','Três maiores mercados: valor','Top three markets: value','US$ FOB',True),('p2','Soma dos quadrados dos valores por produto','Sum of squared product values','(US$ FOB)²',True),('c2','Soma dos quadrados dos valores por mercado','Sum of squared market values','(US$ FOB)²',True)]
RAZOES=[('p1_pct','p1_fob','Maior produto: participação','Largest product share',100,'%'),('p3_pct','p3_fob','Três maiores produtos: participação','Top three product share',100,'%'),('c1_pct','c1_fob','Maior mercado: participação','Largest market share',100,'%'),('c3_pct','c3_fob','Três maiores mercados: participação','Top three market share',100,'%'),('hhi_prod','p2','Concentração por produtos (HHI)','Product concentration (HHI)',10000,'índice 0–10.000'),('hhi_pais','c2','Concentração por mercados (HHI)','Market concentration (HHI)',10000,'índice 0–10.000')]

def definicoes(meta):
 anos=list(range(2013,meta['ano']+1));corte=meta['mes'];out=[]
 def add(id,pt,en,un,fam,helper=False,cut=False,nota='',nota_en='',signed=False,years=None):
  periodos=years or anos;notes={str(y):[f"Janeiro a {MESES[corte-1]if cut else MESES[meta['periodos'][str(y)]-1]} de {y}."+(' Período parcial; não é total de 12 meses.'if(not cut and meta['periodos'][str(y)]<12)else''),f"January to {MONTHS[corte-1]if cut else MONTHS[meta['periodos'][str(y)]-1]} {y}."+(' Partial year, not a 12-month total.'if(not cut and meta['periodos'][str(y)]<12)else'')]for y in periodos}
  desc=(nota+' 'if nota else'')+('Recorte comparável: janeiro a '+MESES[corte-1]+' em todos os anos. 'if cut else'Total do período disponível em cada ano; confira meses_ano e a referência. ')+NOTA
  en_desc=(nota_en+' 'if nota_en else'')+('Comparable window: January to '+MONTHS[corte-1]+' in every year. 'if cut else'Total over each year’s available months; inspect months and reference. ')+NOTA_EN
  out.append(dict(id=id,nome=pt,nome_en=en,unidade=un,unidade_en={'grupos SH4':'HS4 groups','códigos de mercado':'market codes','habitantes':'residents','meses':'months','índice 0–10.000':'0–10,000 index'}.get(un,un),familia=fam,fonte='comex',fonte_nome='MDIC/Secex · Comex Stat',fonte_url=FONTE,descricao=desc,descricao_en=en_desc,anos=periodos,auxiliar=helper,tipo_periodo='anual',recorte='comum'if cut else'observado',com_sinal=signed,notas_anos=notes))
 for flow,pt,en in [('exp','Exportações','Exports'),('imp','Importações','Imports')]:
  for cut in [False,True]:
   for suffix,label,label_en,unit,helper in BASES:
    extra='A contagem inclui países, territórios e destinos estatísticos conforme os códigos MDIC; não é número de empresas.'if suffix=='pais_n'else'Grupos por posição de quatro dígitos do Sistema Harmonizado, conforme código publicado.'if suffix=='prod_n'else''
    extra_en='Count includes countries, territories and statistical destinations as coded by MDIC; not a company count.'if suffix=='pais_n'else'Four-digit Harmonized System headings, using published codes.'if suffix=='prod_n'else''
    add(f'cex_{flow}_{suffix}'+('_c'if cut else''),pt+' · '+label+(' · mesmos meses'if cut else''),en+' · '+label_en+(' · same months'if cut else''),unit,('bases'if helper else'comparavel'if cut else flow),helper,cut,extra,extra_en)
  for suffix,_,label,label_en,factor,unit in RAZOES:
   nota='Concentração calculada sobre os valores FOB: maior participação ou HHI maior indica concentração maior. Em agregados, recalculada sobre todos os registros do recorte; não é média dos municípios. Sem comércio de valor positivo, o indicador é indefinido.'
   en_nota='Computed from FOB values: a larger share or HHI means greater concentration. Aggregates are recomputed from all records in the scope, not averaged across municipalities. Undefined without positive-value trade.'
   add(f'cex_{flow}_{suffix}',pt+' · '+label,en+' · '+label_en,unit,'diversidade',nota=nota,nota_en=en_nota)
  add(f'cex_{flow}_ant_eq',pt+' no ano anterior · mesmos meses',en+' in previous year · same months','US$ FOB','bases',True,nota='Ano anterior usando os mesmos meses disponíveis no ano da linha. Ausente em 2013, pois a aquisição começa em 2013.',years=anos[1:])
  add(f'cex_{flow}_var_pct',pt+' · variação frente ao mesmo período anterior',en+' · change against the same previous period','%','variacao',nota='(Valor do ano / valor anterior nos mesmos meses − 1) × 100. Base anterior zero é indefinida; não se atribui crescimento infinito. A série começa em 2014.',nota_en='(Current value / previous-year value over the same months − 1) × 100. Undefined with a zero prior base; no infinite growth is assigned. Series starts in 2014.',signed=True,years=anos[1:])
 for suffix,pt,en in [('saldo_fob','Saldo comercial','Trade balance'),('corrente_fob','Corrente de comércio','Total trade')]:
  for cut in [False,True]:add('cex_'+suffix+('_c'if cut else''),pt+(' · mesmos meses'if cut else''),en+(' · same months'if cut else''),'US$ FOB','resumo',cut,cut,nota='Exportações menos importações.'if suffix=='saldo_fob'else'Exportações mais importações.',nota_en='Exports minus imports.'if suffix=='saldo_fob'else'Exports plus imports.',signed=suffix=='saldo_fob')
 add('cex_populacao','População de referência','Reference population','habitantes','bases',True)
 out[-1].update(fonte_nome='IBGE / SVS',fonte_url='https://sidra.ibge.gov.br/tabela/6579',descricao='População de referência SVS/IBGE até 2025; estimativa municipal IBGE de julho/2026 para 2026. Não é população vinculada às empresas declarantes.',descricao_en='Reference SVS/IBGE population through 2025; July 2026 municipal IBGE estimates for 2026. Not the population associated with declaring companies.')
 add('cex_meses_ano','Meses disponíveis no ano','Available months in the year','meses','bases',True)
 add('cex_meses_comuns','Meses usados nas comparações','Months used in comparisons','meses','bases',True,True)
 assert len(out)==63 and len({i['id']for i in out})==len(out)and all(len(i['id']+'_cond')<=32 for i in out)
 return out
